INSERT INTO configuracion (clave, valor, tipo, descripcion) VALUES ('terminos_condiciones','["La cotización tiene una validez de 15 días calendario a partir de la fecha de emisión.","Forma de pago: 60% de anticipo para la orden de compra y reserva de equipos y 40% a la puesta en marcha y pruebas de funcionamiento.","Garantía Paneles Solares: 10 años contra defectos de fabricación y garantía de generación lineal de 25 años.","Garantía de Baterías: Entre 5 a 10 años según la referencia y marca del equipo.","Garantía de 6 meses sobre la instalación eléctrica y la fijación estructural frente a defectos de montaje.","La gestión de trámites de legalización, certificación RETIE e inscripción ante el Operador de Red (OR) se sujetará a las agendas y tiempos de respuesta de las entidades. PSC no garantiza el exito de la gestión sin embargo se compromete a apoyarla y colaborar en su gestión.","Refuerzos estructurales en techos, obras civiles de excavación especial o reparación de imperfecciones o filtraciones preexistentes en la cubierta NO están incluidos en la actual propuesta.","Las marcas y referencias de los equipos especificadas en esta propuesta están sujetas a disponibilidad de inventario al momento del anticipo. En caso de requerirse un cambio, se utilizarán equipos de marcas equivalentes o superiores, garantizando que no se afectarán negativamente la calidad, la potencia nominal del sistema ni los tiempos de garantía originalmente ofrecidos.","La presente oferta contempla única y exclusivamente las obras civiles, eléctricas, componentes y actividades descritos de forma explícita en el cuerpo de la propuesta. Cualquier equipo, adecuación, reubicación o trabajo complementario no especificado requerirá la tramitación formal de un adicionales u orden de cambio, la cual deberá ser aprobada por el cliente y generará costos y plazos de entrega independientes."]','string',NULL) ON DUPLICATE KEY UPDATE valor = VALUES(valor);
